  1246	// moduleScopeChange builds a synthetic change for a file whose contents changed
  1247	// but where no named symbol changed. Attributing the edit to a module-level
  1248	// entity (keyed by the file path) keeps module-scope changes visible in the diff
  1249	// rather than emitting a null/empty entry. It returns false when there is no
  1250	// observable content change to report (e.g. a pure rename).
  1251	func moduleScopeChange(path, before, after string, beforeOK, afterOK bool) (EntityChange, bool) {
  1252		switch {
  1253		case afterOK && !beforeOK:
  1254			return EntityChange{Type: "added", Kind: moduleKind, Name: path, AfterStartLine: 1}, true
  1255		case beforeOK && !afterOK:
  1256			return EntityChange{Type: "removed", Kind: moduleKind, Name: path, BeforeStartLine: 1}, true
  1257		case beforeOK && afterOK && before != after:
  1258			return EntityChange{Type: "body_changed", Kind: moduleKind, Name: path, BeforeStartLine: 1, AfterStartLine: 1}, true
  1259		default:
  1260			return EntityChange{}, false
  1261		}
  1262	}
